import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";import"./chunks/assets.CGKUPeQw.js";var i=JSON.parse(`{"title":"AireForms Release Notes — 2024","description":"","frontmatter":{},"headers":[],"relativePath":"aireblock-releases/AireForms/aireforms-2024.md","filePath":"aireblock-releases/AireForms/aireforms-2024.md","lastUpdated":1786968286000}`),a={name:`aireblock-releases/AireForms/aireforms-2024.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="aireforms-release-notes-—-2024" tabindex="-1"><span class="fsc-product"><img src="/aireforms-icon.png"> AireForms Release Notes — 2024</span> <a class="header-anchor" href="#aireforms-release-notes-—-2024" aria-label="Permalink to “AireForms Release Notes — 2024”">​</a></h1><p>This page contains the AireForms releases published during 2024.</p><h2 id="version-9-6-0-—-rate-limiting-translation-improvements" tabindex="-1">Version 9.6.0 — Rate Limiting &amp; Translation Improvements <a class="header-anchor" href="#version-9-6-0-—-rate-limiting-translation-improvements" aria-label="Permalink to “Version 9.6.0 — Rate Limiting &amp; Translation Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> November 12, 2024</p></blockquote><h3 id="⚡-improvements" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved rate limiting for unauthenticated routes across a scaled-out service</li></ul><h3 id="🐞-bug-fixes" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue with reference data translations</li><li>Fixed an issue where the debug tools could appear behind the banner, making them difficult to close</li><li>Fixed an issue where a Lazy Button Select control could incorrectly be marked as multi-select</li></ul><h2 id="version-9-5-0-—-aireaudit-integration" tabindex="-1">Version 9.5.0 — AireAudit Integration <a class="header-anchor" href="#version-9-5-0-—-aireaudit-integration" aria-label="Permalink to “Version 9.5.0 — AireAudit Integration”">​</a></h2><blockquote><p><strong>Release Date:</strong> September 11, 2024</p></blockquote><h3 id="✨-new-features" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>The Designer now sends basic audit events to AireAudit</li></ul><h2 id="version-9-4-1-—-definition-service-performance" tabindex="-1">Version 9.4.1 — Definition Service Performance <a class="header-anchor" href="#version-9-4-1-—-definition-service-performance" aria-label="Permalink to “Version 9.4.1 — Definition Service Performance”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 12, 2024</p></blockquote><h3 id="⚡-improvements-1" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-1" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Changed the file system implementation used by the Definition Service to substantially improve the performance of calls that use form definitions</li><li>Reduced the number of calls made to the Definition Service when using the Subject Forms APIs</li></ul><h2 id="version-9-4-0-—-release-version-view-mode-fixes" tabindex="-1">Version 9.4.0 — Release Version &amp; View Mode Fixes <a class="header-anchor" href="#version-9-4-0-—-release-version-view-mode-fixes" aria-label="Permalink to “Version 9.4.0 — Release Version &amp; View Mode Fixes”">​</a></h2><blockquote><p><strong>Release Date:</strong> August 1, 2024</p></blockquote><h3 id="🐞-bug-fixes-1" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-1" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where the release version was no longer displayed in the UI</li><li>Fixed an issue where a building block configured in view mode within an edit context incorrectly had the <code>displayName</code> attribute applied to its data elements</li></ul><h2 id="version-9-3-0-—-translation-escaping-fix" tabindex="-1">Version 9.3.0 — Translation Escaping Fix <a class="header-anchor" href="#version-9-3-0-—-translation-escaping-fix" aria-label="Permalink to “Version 9.3.0 — Translation Escaping Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> July 27, 2024</p></blockquote><h3 id="🐞-bug-fixes-2" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-2" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue with escaping control characters in automatically translated text</li></ul><h2 id="version-9-2-0-—-tenant-subdomains-extracts-rate-limiting" tabindex="-1">Version 9.2.0 — Tenant Subdomains, Extracts &amp; Rate Limiting <a class="header-anchor" href="#version-9-2-0-—-tenant-subdomains-extracts-rate-limiting" aria-label="Permalink to “Version 9.2.0 — Tenant Subdomains, Extracts &amp; Rate Limiting”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 25, 2024</p></blockquote><h3 id="⚡-improvements-2" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-2" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Added support for tenant-based subdomains in the Designer</li><li>Removed the default reference data key and version for Lazy and Dynamic Dropdown controls</li><li>Added support for extracting translatable controls</li><li>Added rate limiting to unauthenticated runtime routes</li></ul><h2 id="version-9-1-0-—-tenant-environment-visibility" tabindex="-1">Version 9.1.0 — Tenant &amp; Environment Visibility <a class="header-anchor" href="#version-9-1-0-—-tenant-environment-visibility" aria-label="Permalink to “Version 9.1.0 — Tenant &amp; Environment Visibility”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 7, 2024</p></blockquote><h3 id="⚡-improvements-3" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-3" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>The Designer now displays the currently logged-in tenant and environment</li></ul><h2 id="version-9-0-0-—-designer-data-store-migration" tabindex="-1">Version 9.0.0 — Designer Data Store Migration <a class="header-anchor" href="#version-9-0-0-—-designer-data-store-migration" aria-label="Permalink to “Version 9.0.0 — Designer Data Store Migration”">​</a></h2><blockquote><p><strong>Release Date:</strong> June 4, 2024</p></blockquote><h3 id="⚠️-important" tabindex="-1">⚠️ Important <a class="header-anchor" href="#⚠️-important" aria-label="Permalink to “⚠️ Important”">​</a></h3><ul><li>Removed the Designer saved-block migration script</li><li>Removed support for the old Designer data store</li><li>A migration using version 8.5.5 must be completed before upgrading beyond this release</li></ul><h2 id="version-8-5-5-—-centralised-tenanted-designer-storage" tabindex="-1">Version 8.5.5 — Centralised Tenanted Designer Storage <a class="header-anchor" href="#version-8-5-5-—-centralised-tenanted-designer-storage" aria-label="Permalink to “Version 8.5.5 — Centralised Tenanted Designer Storage”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 23, 2024</p></blockquote><h3 id="⚠️-important-1" tabindex="-1">⚠️ Important <a class="header-anchor" href="#⚠️-important-1" aria-label="Permalink to “⚠️ Important”">​</a></h3><ul><li>Added a migration script to move blocks saved in the Designer to a centralised, tenanted location</li><li>The previous data store is no longer supported from version 9.0.0 onwards</li></ul><h3 id="✨-new-features-1" tabindex="-1">✨ New Features <a class="header-anchor" href="#✨-new-features-1" aria-label="Permalink to “✨ New Features”">​</a></h3><ul><li>Added support for Client Credentials when calling AireGlu endpoints through the AireGlu Deliverer</li><li>Added Client Credentials support for AireGlu reference data integrations</li><li>Added Client Credentials support for AireGlu server-side calculation integrations</li></ul><h2 id="version-8-4-6-—-selection-other-value-fix" tabindex="-1">Version 8.4.6 — Selection Other Value Fix <a class="header-anchor" href="#version-8-4-6-—-selection-other-value-fix" aria-label="Permalink to “Version 8.4.6 — Selection Other Value Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 16, 2024</p></blockquote><h3 id="🐞-bug-fixes-3" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-3" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where controls referencing the <code>otherValue</code> of selection-based controls did not receive the correct value</li></ul><h2 id="version-8-4-4-—-form-history-api-fix" tabindex="-1">Version 8.4.4 — Form History API Fix <a class="header-anchor" href="#version-8-4-4-—-form-history-api-fix" aria-label="Permalink to “Version 8.4.4 — Form History API Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> May 6, 2024</p></blockquote><h3 id="🐞-bug-fixes-4" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-4" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue when calling the Form History APIs</li></ul><h2 id="version-8-4-4-—-selection-display-name-fix" tabindex="-1">Version 8.4.4 — Selection Display Name Fix <a class="header-anchor" href="#version-8-4-4-—-selection-display-name-fix" aria-label="Permalink to “Version 8.4.4 — Selection Display Name Fix”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 29, 2024</p></blockquote><h3 id="🐞-bug-fixes-5" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-5" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed an issue where controls referencing the <code>displayName</code> of selection-based controls did not receive the correct value</li></ul><h2 id="version-8-4-3-—-data-only-building-block-validation" tabindex="-1">Version 8.4.3 — Data-Only Building Block Validation <a class="header-anchor" href="#version-8-4-3-—-data-only-building-block-validation" aria-label="Permalink to “Version 8.4.3 — Data-Only Building Block Validation”">​</a></h2><blockquote><p><strong>Release Date:</strong> April 22, 2024</p></blockquote><h3 id="🐞-bug-fixes-6" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-6" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a validation issue when using a data-only enabled building block</li></ul><h2 id="version-8-4-0-—-date-validation-designer-improvements" tabindex="-1">Version 8.4.0 — Date Validation &amp; Designer Improvements <a class="header-anchor" href="#version-8-4-0-—-date-validation-designer-improvements" aria-label="Permalink to “Version 8.4.0 — Date Validation &amp; Designer Improvements”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 1, 2024</p></blockquote><h3 id="⚡-improvements-4" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-4" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Optional Date controls are now validated when they contain an invalid date, such as <code>31-Apr-2024</code></li><li>Users are prompted for confirmation before overwriting an existing building block during import</li></ul><h3 id="🐞-bug-fixes-7" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-7" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Fixed a display issue on mobile devices for forms with both discard and autosave enabled</li><li>Various Designer bug fixes</li></ul><h2 id="version-8-3-0-—-form-instance-creator-authorisation" tabindex="-1">Version 8.3.0 — Form Instance Creator Authorisation <a class="header-anchor" href="#version-8-3-0-—-form-instance-creator-authorisation" aria-label="Permalink to “Version 8.3.0 — Form Instance Creator Authorisation”">​</a></h2><blockquote><p><strong>Release Date:</strong> March 1, 2024</p></blockquote><h3 id="⚡-improvements-5" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-5" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>The form instance creator is now sent to the authority check API</li></ul><h3 id="🔧-dependencies" tabindex="-1">🔧 Dependencies <a class="header-anchor" href="#🔧-dependencies" aria-label="Permalink to “🔧 Dependencies”">​</a></h3><ul><li>Updated Forms.Api to 4.2.0, which passes the creating user identifier to the form instance authority check</li><li>Updated Forms.Persistence to 3.2.0, where <code>CompositeInstanceVersion</code> is required to return form instance creator details</li></ul><h2 id="version-8-2-3-—-score-layout-system-user-support" tabindex="-1">Version 8.2.3 — Score Layout &amp; System User Support <a class="header-anchor" href="#version-8-2-3-—-score-layout-system-user-support" aria-label="Permalink to “Version 8.2.3 — Score Layout &amp; System User Support”">​</a></h2><blockquote><p><strong>Release Date:</strong> February 1, 2024</p></blockquote><h3 id="⚡-improvements-6" tabindex="-1">⚡ Improvements <a class="header-anchor" href="#⚡-improvements-6" aria-label="Permalink to “⚡ Improvements”">​</a></h3><ul><li>Improved the layout of multiple score elements on smaller screens</li></ul><h3 id="🐞-bug-fixes-8" tabindex="-1">🐞 Bug Fixes <a class="header-anchor" href="#🐞-bug-fixes-8" aria-label="Permalink to “🐞 Bug Fixes”">​</a></h3><ul><li>Various Designer bug fixes</li></ul><h3 id="🔧-dependencies-1" tabindex="-1">🔧 Dependencies <a class="header-anchor" href="#🔧-dependencies-1" aria-label="Permalink to “🔧 Dependencies”">​</a></h3><ul><li>Updated Forms.Api to 4.1.0</li><li>Updated Forms.Persistence to 3.1.0</li><li>Updated Forms.Abstractions to 1.1.0</li><li>Added a new System user type</li></ul>`,78)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};